"""matplotlib.category — categorical axis support.

Provides the same string→float mapping upstream uses when callers pass
strings as data. The mapping is owned by a :class:`UnitData` instance
attached to the axis; the converter looks it up to map back and forth.
"""

import numpy as _np


class StrCategoryConverter:
    """Convert string categories to float positions, mirroring upstream.

    Upstream's StrCategoryConverter stores the mapping in ``axis.units``
    (a :class:`UnitData`) — this matches that contract.
    """

    @staticmethod
    def convert(value, unit, axis):
        """Map each value (string or array of strings) through
        ``unit._mapping``. Numeric values pass through unchanged."""
        if isinstance(value, str):
            if isinstance(unit, UnitData):
                unit.update([value])
                return float(unit._mapping[value])
            return 0.0
        if hasattr(value, '__iter__') and not isinstance(value, (bytes, _np.ndarray)):
            vals = list(value)
            if vals and any(isinstance(v, str) for v in vals):
                if not isinstance(unit, UnitData):
                    unit = UnitData(vals)
                else:
                    unit.update([v for v in vals if isinstance(v, str)])
                return _np.array([
                    float(unit._mapping[v]) if isinstance(v, str) else float(v)
                    for v in vals])
        try:
            return _np.asarray(value, dtype=float)
        except (TypeError, ValueError):
            return _np.zeros(len(value) if hasattr(value, '__len__') else 1)

    @staticmethod
    def axisinfo(unit, axis):
        """Return an :class:`AxisInfo` with the categorical locator/formatter
        pre-bound so the axis automatically shows category labels."""
        from matplotlib.units import AxisInfo
        if not isinstance(unit, UnitData):
            return AxisInfo()
        return AxisInfo(majloc=StrCategoryLocator(unit._mapping),
                         majfmt=StrCategoryFormatter(unit._mapping))

    @staticmethod
    def default_units(data, axis):
        """Initialise a fresh :class:`UnitData` from the supplied data."""
        # If the axis already has a UnitData, extend it; else create one.
        existing = getattr(axis, 'units', None)
        if isinstance(existing, UnitData):
            existing.update(data)
            return existing
        return UnitData(data)


class StrCategoryLocator:
    """Place ticks at the integer position of each registered category."""

    def __init__(self, units_mapping):
        self._units = units_mapping

    def __call__(self):
        return self.tick_values(None, None)

    def tick_values(self, vmin, vmax):
        """Return tick positions — one per category, filtered to the
        requested ``[vmin, vmax]`` window."""
        positions = list(self._units.values())
        if vmin is None or vmax is None:
            return positions
        return [p for p in positions if vmin <= p <= vmax]


class StrCategoryFormatter:
    """Render numeric positions back to their category labels."""

    def __init__(self, units_mapping):
        self._units = units_mapping
        # Build a reverse map for O(1) lookup at format time.
        self._reverse = {v: k for k, v in units_mapping.items()}

    def __call__(self, x, pos=None):
        if x in self._reverse:
            return self._reverse[x]
        # Allow float-equality lookup (positions may have been rounded).
        try:
            xi = int(round(x))
            if xi in self._reverse:
                return self._reverse[xi]
        except Exception:
            pass
        return ''

    def format_ticks(self, values):
        """Format a list of tick values to a list of label strings."""
        return [self(v, i) for i, v in enumerate(values)]


class UnitData:
    """Ordered mapping ``label → integer position``. Built incrementally
    as new categories are seen so the position is stable for the lifetime
    of the axis (mirrors upstream's :class:`matplotlib.category.UnitData`)."""

    def __init__(self, data=None):
        self._mapping = {}
        self._counter = 0
        if data is not None:
            self.update(data)

    def update(self, data):
        """Insert any new categories from ``data`` at the next free slot."""
        for d in data:
            if isinstance(d, str):
                s = d
            else:
                # Non-string entries are stored as numeric positions
                # directly (matches upstream's behavior — only strings
                # consume the next category slot).
                continue
            if s not in self._mapping:
                self._mapping[s] = self._counter
                self._counter += 1

    def __len__(self):
        return len(self._mapping)


# Auto-register the converter so users can plot string-keyed data without
# explicit setup. Mirrors what upstream does at import time.
from matplotlib.units import registry as _u_registry
_u_registry[str] = StrCategoryConverter
_u_registry[bytes] = StrCategoryConverter
